// ADMIN LOGIN
// ═══════════════════════════════════════════════════════════════════════════════
function AdminLogin({ onLogin, onBack }) {
  const [password, setPassword] = useState("");
  const [error, setError] = useState(false);

  function attempt() {
    if (password === "admin123") onLogin();
    else setError(true);
  }

  return (
    <div style={{ minHeight: "100vh", background: T.bg, fontFamily: T.fontSans, display: "flex", alignItems: "center", justifyContent: "center", padding: 24 }}>
      <style>{`* { box-sizing: border-box; margin: 0; padding: 0; }`}</style>
      <div style={{ width: "100%", maxWidth: 360 }}>
        {/* Brand */}
        <img src={LOGO_SRC} alt="PG Create" style={{ height: 72, width: "auto", marginBottom: 12, filter: "brightness(0)" }} />

        <div style={{ background: T.surface, border: `1px solid ${T.border}`, borderRadius: 8, padding: 28 }}>
          <p style={{ fontFamily: T.fontMono, fontSize: 10, color: T.textXMuted, letterSpacing: "0.1em", textTransform: "uppercase", marginBottom: 6 }}>RESTRICTED</p>
          <h2 style={{ fontFamily: T.fontSans, fontSize: 26, fontWeight: 300, color: T.text, marginBottom: 24, letterSpacing: "-0.5px" }}>Admin login</h2>

          <label style={{ display: "block", marginBottom: 16 }}>
            <span style={{ display: "block", fontFamily: T.fontMono, fontSize: 10, color: T.textMuted, letterSpacing: "0.1em", textTransform: "uppercase", marginBottom: 6 }}>Password</span>
            <input
              type="password"
              value={password}
              autoFocus
              onChange={e => { setPassword(e.target.value); setError(false); }}
              onKeyDown={e => e.key === "Enter" && attempt()}
              placeholder="Enter password"
              style={{
                width: "100%", padding: "10px 12px",
                border: `1px solid ${error ? T.danger : T.border}`,
                borderRadius: 4, fontFamily: T.fontSans, fontSize: 14,
                color: T.text, background: T.bg, outline: "none",
              }}
            />
            {error && <p style={{ fontFamily: T.fontSans, fontSize: 12, color: T.danger, marginTop: 5 }}>Incorrect password.</p>}
          </label>

          <button
            onClick={attempt}
            style={{
              width: "100%", padding: "10px", background: T.text, color: T.bg,
              border: "none", borderRadius: 4, fontFamily: T.fontSans,
              fontSize: 14, fontWeight: 500, cursor: "pointer", marginBottom: 12,
            }}
          >Sign in</button>

          <button onClick={onBack} style={{ width: "100%", background: "none", border: `1px solid ${T.border}`, borderRadius: 4, padding: 10, fontFamily: T.fontSans, fontSize: 13, color: T.textMuted, cursor: "pointer" }}>
            ← Back to site
          </button>
        </div>

        <p style={{ fontFamily: T.fontMono, fontSize: 10, color: T.textXMuted, textAlign: "center", marginTop: 20, letterSpacing: "0.08em" }}>
          DEMO: admin123
        </p>
      </div>
    </div>
  );
}

